{
  "root_causes": [
    {
      "service": "ts-travel-service",
      "fault_kind": "http_wrong_status_code",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.attr_http_response_status_code client_status, s.service_name callee, s.span_name, s.attr_http_response_status_code server_status, count(*) n, round(quantile_cont(c.duration,0.5)/1e6,1) client_med_ms, round(quantile_cont(s.duration,0.5)/1e6,1) server_med_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-travel-service' AND c.attr_span_kind='Client' AND s.service_name='ts-basic-service' GROUP BY ALL ORDER BY n DESC",
          "claim": "Travel's client calls to basic /basicservice/basic/travels record 408 while basic's server spans return 200 with similar latency."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, left(message,200) msg, count(*) c FROM abnormal_logs WHERE service_name='ts-travel-service' AND level='SEVERE' GROUP BY 1,2,3 ORDER BY c DESC LIMIT 5",
          "claim": "Travel-service logs about 1,050 SEVERE exceptions from HttpClientErrorException 408 Request Timeout on basic-service calls, with valid JSON bodies."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind kind, attr_http_response_status_code st, count(*) n FROM abnormal_traces WHERE service_name='ts-travel-service' AND span_name LIKE '%trips/left%' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "Travel's POST /trips/left server spans return 500 for about 1,050 requests in the abnormal window, against normal behaviour before the change."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.attr_http_response_status_code cst, s.service_name callee, s.span_name, s.attr_http_response_status_code sst, count(*) n, round(quantile_cont(c.duration,0.5)/1e6,1) c_med FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND c.service_name='ts-route-plan-service' AND s.service_name='ts-travel-service' GROUP BY ALL ORDER BY n DESC",
          "claim": "Route-plan's calls to travel /trips/left return 500 in about 828 cases, with multi-second client times, mirroring travel's failures."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.attr_http_response_status_code cst, s.service_name callee, s.attr_http_response_status_code sst, count(*) n, round(quantile_cont(c.duration,0.5)/1e6,1) c_med, round(quantile_cont(s.duration,0.5)/1e6,1) s_med FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND s.service_name='ts-route-plan-service' GROUP BY ALL ORDER BY n DESC",
          "claim": "Travel-plan's POST calls to route-plan return 504 after about 60 s, while route-plan's server answers 500 after about 4.8 s."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind kind, attr_http_response_status_code st, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) med_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-ui-dashboard') AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' GROUP BY ALL ORDER BY 1,2",
          "claim": "Travel-plan's travelPlan endpoints return 500 after about 60 s, and ui-dashboard's travelPlan server spans are slow as a result."
        }
      ]
    }
  ]
}
